/**
 * DCM Core — Site search (command bar)
 * Searches every indexable page (search/index-<lang>.json, generated by
 * generate_search_index.py) plus the entity/research graph (api/v1/*.json).
 * Open with the navbar search button, Ctrl/⌘+K, or window.dcmToggleGlobalSearch().
 */
(function () {
    if (window.dcmSearchEngineLoaded) return;
    window.dcmSearchEngineLoaded = true;

    // Site is served from the domain root: always use absolute paths.
    const LANG = (document.documentElement.lang || '').toLowerCase().startsWith('fr') ||
        window.location.pathname.startsWith('/fr/') ? 'fr' : 'en';
    const LANG_ROOT = '/' + LANG + '/';
    const API_PREFIX = '/api/v1/';
    const INDEX_URL = '/search/index-' + LANG + '.json';
    const CSS_URL = '/css/dcm-search-engine.css';

    let SEARCH_GRAPH = [];
    let PAGES = null;          // loaded lazily on first open
    let pagesLoading = null;
    let activeIndex = -1;
    let visibleHits = [];

    async function hydrateKnowledgeGraph() {
        const endpoints = ['entities.json', 'narratives.json', 'research.json', 'risks.json', 'system.json'];
        const results = await Promise.all(endpoints.map(f =>
            fetch(API_PREFIX + f).then(r => (r.ok ? r.json() : null)).catch(() => null)));
        results.forEach(ds => { if (ds && Array.isArray(ds.data)) SEARCH_GRAPH.push(...ds.data); });
        if (!SEARCH_GRAPH.length) SEARCH_GRAPH = FALLBACK_GRAPH;
    }

    function loadPages() {
        if (PAGES) return Promise.resolve(PAGES);
        if (!pagesLoading) {
            pagesLoading = fetch(INDEX_URL)
                .then(r => (r.ok ? r.json() : { pages: [] }))
                .then(d => {
                    PAGES = (d.pages || []).map(p => Object.assign(p, {
                        _t: norm(p.t), _h: norm(p.h), _k: norm(p.k), _d: norm(p.d), _u: norm(p.u)
                    }));
                    updateStats();
                    return PAGES;
                })
                .catch(() => (PAGES = []));
        }
        return pagesLoading;
    }

    const FALLBACK_GRAPH = [
        {
            id: 'sig-2026-12',
            category: 'signal',
            title: { en: 'Weekly Signal: Reserve Fragmentation', fr: 'Signal Hebdo : Fragmentation des Réserves' },
            desc: { en: 'DCM-SIG-2026-12 · Structural arbitrage pivot under MiCA mandates', fr: 'DCM-SIG-2026-12 · Pivot d\'arbitrage structurel sous MiCA' },
            keywords: ['signal', 'mica', 'reserve', 'custody', 'arbitrage', 'weekly'],
            urlPath: {
                en: 'intelligence/signals.html',
                fr: 'intelligence/signaux.html'
            },
            relatedIds: ['entity-circle', 'risk-mica']
        },
        {
            id: 'entity-blackrock',
            category: 'entity',
            title: { en: 'BlackRock', fr: 'BlackRock' },
            desc: { en: 'Asset Management · Grade A · SEC registered issuer', fr: 'Gestion d\'Actifs · Note A · Émetteur SEC' },
            keywords: ['blackrock', 'buidl', 'securitize', 'asset', 'mmf'],
            urlPath: 'entities/blackrock.html',
            relatedIds: ['wp-buidl', 'risk-buidl']
        },
        {
            id: 'entity-jpm',
            category: 'entity',
            title: { en: 'JPMorgan Onyx', fr: 'JPMorgan Onyx' },
            desc: { en: 'Commercial Banking · Grade AA · Wholesale settlement ledger', fr: 'Banque Commerciale · Note AA · Registre de gros' },
            keywords: ['jpmorgan', 'jpm', 'onyx', 'coin', 'repo'],
            urlPath: 'entities/jpm-onyx.html',
            relatedIds: ['risk-jpm']
        },
        {
            id: 'entity-circle',
            category: 'entity',
            title: { en: 'Circle / USDC', fr: 'Circle / USDC' },
            desc: { en: 'Digital Infra · Grade AA · Atomic payment & CCTP rails', fr: 'Infra Digitale · Note AA · Paiement atomique & rails CCTP' },
            keywords: ['circle', 'usdc', 'stablecoin', 'cctp'],
            urlPath: 'entities/circle.html',
            relatedIds: ['risk-usdc']
        },
        {
            id: 'entity-forge',
            category: 'entity',
            title: { en: 'SG Forge', fr: 'SG Forge' },
            desc: { en: 'Investment Banking · Grade A · Eur CoinVertible issuer', fr: 'Banque d\'Investissement · Note A · Émetteur Eur CoinVertible' },
            keywords: ['societe generale', 'sg', 'forge', 'eurcv', 'mica'],
            urlPath: 'observatory/risk-radar.html',
            relatedIds: []
        },
        {
            id: 'wp-global',
            category: 'research',
            title: { en: 'Global Tokenization Report 2026', fr: 'Rapport de Tokenisation Mondial 2026' },
            desc: { en: 'DCM-WP-2026-01 · Quantitative institutional market audit', fr: 'DCM-WP-2026-01 · Audit de marché institutionnel' },
            keywords: ['report', 'audit', 'market', 'wp-2026-01'],
            urlPath: 'research/terminal.html',
            relatedIds: []
        },
        {
            id: 'wp-stablecoin-eu',
            category: 'research',
            title: { en: 'European Stablecoin Structure', fr: 'Structure Stablecoins Europe' },
            desc: { en: 'DCM-WP-2026-04 · MiCA liquidity migration paper', fr: 'DCM-WP-2026-04 · Papier sur la migration de liquidité MiCA' },
            keywords: ['stablecoin', 'mica', 'europe', 'wp-2026-04'],
            urlPath: {
                en: 'research/european-stablecoin-market-structure-2026.html',
                fr: 'research/structure-marche-stablecoins-europeens-2026.html'
            },
            relatedIds: ['risk-mica']
        },
        {
            id: 'risk-buidl',
            category: 'risk',
            title: { en: 'BlackRock BUIDL Risk Profile', fr: 'Profil de Risque BUIDL' },
            desc: { en: 'Grade A · Vector scores: TECH:A CUST:AA LEGAL:A LIQ:BB', fr: 'Note A · Scores vectoriels : TECH:A CUST:AA' },
            keywords: ['risk', 'buidl', 'blackrock'],
            urlPath: 'observatory/risk-radar.html',
            relatedIds: []
        },
        {
            id: 'narratives-thematic',
            category: 'narrative',
            title: { en: 'Market Narratives Matrix', fr: 'Thèses de Marché Institutionnelles' },
            desc: { en: 'Thematic overlays linking macro drivers to token assets', fr: 'Couches thématiques reliant les vecteurs macro aux actifs' },
            keywords: ['narratives', 'thesis', 'thèses', 'macro'],
            urlPath: 'intelligence/narratives.html',
            relatedIds: ['hub-central']
        },
        {
            id: 'hub-central',
            category: 'hub',
            title: { en: 'Command Center Hub', fr: 'Centre de Commande Intelligence' },
            desc: { en: 'Central dashboard orchestrating real-time market vectors', fr: 'Tableau de bord central pilotant les vecteurs en temps réel' },
            keywords: ['hub', 'command', 'dashboard'],
            urlPath: 'intelligence/hub.html',
            relatedIds: []
        }
    ];

    const L = {
        en: {
            placeholder: 'Search the site: MiCA, DORA, BUIDL, APR vs APY…',
            suggested: 'Suggested searches',
            related: 'Related intelligence',
            entities: 'Entities & datasets',
            pages: 'Pages',
            none: 'No results. Try another word or a shorter query.',
            loading: 'Loading the index…',
            stats: n => n + ' pages indexed',
            tip: 'Tip: press <kbd>Ctrl</kbd> + <kbd>K</kbd> (<kbd>⌘</kbd> + <kbd>K</kbd> on Mac) to open search from any page.',
            footer: '<span><kbd>↑↓</kbd> Select</span><span><kbd>↵</kbd> Open</span><span><kbd>Esc</kbd> Close</span>',
            button: 'Search',
            suggestions: ['MiCA', 'DORA', 'DLT Pilot Regime', 'BUIDL', 'APR vs APY', 'Tokenized treasuries'],
            badge: { entity: 'Entity', research: 'Research', risk: 'Risk profile', monitor: 'Monitor', timeline: 'Timeline', hub: 'Hub', narrative: 'Narrative', signal: 'Signal' }
        },
        fr: {
            placeholder: 'Rechercher sur le site : MiCA, DORA, BUIDL, APR vs APY…',
            suggested: 'Recherches suggérées',
            related: 'Éléments liés',
            entities: 'Entités et données',
            pages: 'Pages',
            none: 'Aucun résultat. Essayez un autre mot ou une requête plus courte.',
            loading: 'Chargement de l\'index…',
            stats: n => n + ' pages indexées',
            tip: 'Astuce : <kbd>Ctrl</kbd> + <kbd>K</kbd> (<kbd>⌘</kbd> + <kbd>K</kbd> sur Mac) ouvre la recherche depuis n\'importe quelle page.',
            footer: '<span><kbd>↑↓</kbd> Naviguer</span><span><kbd>↵</kbd> Ouvrir</span><span><kbd>Esc</kbd> Fermer</span>',
            button: 'Rechercher',
            suggestions: ['MiCA', 'DORA', 'Régime pilote DLT', 'BUIDL', 'APR vs APY', 'Bons du Trésor tokenisés'],
            badge: { entity: 'Entité', research: 'Recherche', risk: 'Profil risque', monitor: 'Moniteur', timeline: 'Chronologie', hub: 'Hub', narrative: 'Narratif', signal: 'Signal' }
        }
    }[LANG];

    // ---------- helpers ----------
    function norm(s) {
        return (s || '').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
    }
    function esc(s) {
        return (s || '').toString().replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    }
    function pick(v) { return (v && typeof v === 'object') ? (v[LANG] || v.en || v.fr || '') : (v || ''); }
    function graphHref(item) {
        const p = pick(item.urlPath);
        return p.startsWith('/') ? p : LANG_ROOT + p;
    }

    // ---------- UI ----------
    function initSearchEngine() {
        if (!document.querySelector('link[href="' + CSS_URL + '"]')) {
            const link = document.createElement('link');
            link.rel = 'stylesheet';
            link.href = CSS_URL;
            document.head.appendChild(link);
        }
        const overlay = document.createElement('div');
        overlay.id = 'dcm-search-engine-overlay';
        overlay.className = 'dcm-search-overlay';
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');
        overlay.setAttribute('aria-label', L.button);
        overlay.innerHTML = `
            <div class="dcm-search-container">
                <div class="dcm-search-header">
                    <i class="fas fa-search dcm-search-icon" aria-hidden="true"></i>
                    <input type="search" id="dcm-search-input-node" class="dcm-search-input" placeholder="${esc(L.placeholder)}" autocomplete="off" spellcheck="false" aria-label="${esc(L.button)}">
                    <button type="button" class="dcm-search-kbd-escape" aria-label="Esc">esc</button>
                </div>
                <div id="dcm-search-results-stream" class="dcm-search-results" role="listbox"></div>
                <div class="dcm-search-footer">
                    <div class="dcm-footer-instructions">${L.footer}</div>
                    <div class="dcm-footer-stats" id="dcm-search-stats"></div>
                </div>
            </div>`;
        document.body.appendChild(overlay);

        const input = document.getElementById('dcm-search-input-node');
        window.addEventListener('keydown', function (e) {
            if ((e.metaKey || e.ctrlKey) && (e.key === 'k' || e.key === 'K')) {
                e.preventDefault();
                isOpen() ? closeOverlay() : openOverlay();
            } else if (e.key === 'Escape' && isOpen()) {
                closeOverlay();
            }
        });
        overlay.addEventListener('mousedown', e => { if (e.target === overlay) closeOverlay(); });
        overlay.querySelector('.dcm-search-kbd-escape').addEventListener('click', closeOverlay);
        let timer = null;
        input.addEventListener('input', function () {
            clearTimeout(timer);
            const q = this.value;
            timer = setTimeout(() => runSearch(q), 80);
        });
        input.addEventListener('keydown', function (e) {
            if (e.key === 'ArrowDown') { e.preventDefault(); moveSelection(1); }
            else if (e.key === 'ArrowUp') { e.preventDefault(); moveSelection(-1); }
            else if (e.key === 'Enter') { e.preventDefault(); triggerActiveSelection(); }
        });

        wireTriggers();
        renderEmptyState();
    }

    // Visible entry points: navbar button (or a floating button) + legacy triggers.
    function wireTriggers() {
        document.querySelectorAll('.nav-search-trigger, #search-trigger, [data-dcm-search]').forEach(el => {
            if (!el.dataset.dcmSearchWired) {
                el.dataset.dcmSearchWired = '1';
                el.addEventListener('click', e => { e.preventDefault(); openOverlay(); });
            }
        });
        if (document.querySelector('.dcm-search-nav-btn, .dcm-search-fab')) return;
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.setAttribute('aria-label', L.button);
        btn.title = L.button + ' (Ctrl+K)';
        btn.innerHTML = '<i class="fas fa-search" aria-hidden="true"></i><span class="dcm-search-btn-label">' + esc(L.button) + '</span>';
        btn.addEventListener('click', openOverlay);
        const actions = document.querySelector('.navbar-pro .nav-actions, nav .nav-actions');
        if (actions) {
            btn.className = 'dcm-search-nav-btn';
            actions.insertBefore(btn, actions.firstChild);
        } else if (!document.querySelector('[onclick*="dcmToggleGlobalSearch"]')) {
            btn.className = 'dcm-search-fab';
            document.body.appendChild(btn);
        }
    }

    function isOpen() {
        const o = document.getElementById('dcm-search-engine-overlay');
        return !!(o && o.classList.contains('active'));
    }
    function openOverlay() {
        const overlay = document.getElementById('dcm-search-engine-overlay');
        if (!overlay) return;
        overlay.style.display = 'flex';
        document.documentElement.style.overflow = 'hidden';
        setTimeout(() => {
            overlay.classList.add('active');
            const input = document.getElementById('dcm-search-input-node');
            input.focus();
            input.select();
        }, 20);
        updateStats();
        loadPages().then(() => {
            const q = document.getElementById('dcm-search-input-node').value;
            if (q.trim()) runSearch(q);
        });
    }
    function closeOverlay() {
        const overlay = document.getElementById('dcm-search-engine-overlay');
        if (!overlay) return;
        overlay.classList.remove('active');
        document.documentElement.style.overflow = '';
        setTimeout(() => { overlay.style.display = 'none'; }, 200);
    }
    function updateStats() {
        const el = document.getElementById('dcm-search-stats');
        if (el) el.textContent = PAGES ? L.stats(PAGES.length) : '';
    }

    // ---------- search ----------
    function scorePage(p, tokens, phrase) {
        let score = 0;
        for (const t of tokens) {
            let s = 0;
            if (p._t.includes(t)) s += 10;
            if (p._h.includes(t)) s += 6;
            if (p._k.includes(t)) s += 3;
            if (p._d.includes(t)) s += 2;
            if (p._u.includes(t)) s += 2;
            if (!s) return 0;            // every word must match somewhere
            score += s;
        }
        score += p.w || 0;                // editorial pages up, fragments/modules down
        if (phrase.length > 3 && p._t.includes(phrase)) score += 15;
        else if (phrase.length > 3 && (p._h.includes(phrase) || p._d.includes(phrase))) score += 6;
        return score;
    }

    function runSearch(raw) {
        const stream = document.getElementById('dcm-search-results-stream');
        const phrase = norm(raw).trim();
        if (!phrase) { renderEmptyState(); return; }
        const tokens = phrase.split(/[\s,;:/]+/).filter(t => t.length > 1 || /\d/.test(t));
        if (!tokens.length) { renderEmptyState(); return; }

        const graphHits = SEARCH_GRAPH.filter(item => {
            const hay = norm(pick(item.title) + ' ' + pick(item.desc) + ' ' + (item.keywords || []).join(' '));
            return tokens.every(t => hay.includes(t));
        }).slice(0, 6).map(item => ({
            href: graphHref(item), title: pick(item.title), desc: pick(item.desc),
            badge: L.badge[item.category] || item.category, badgeClass: 'badge-' + item.category
        }));

        const seen = new Set(graphHits.map(h => h.href));
        const pageHits = (PAGES || [])
            .map(p => ({ p, s: scorePage(p, tokens, phrase) }))
            .filter(x => x.s > 0 && !seen.has(x.p.u))
            .sort((a, b) => b.s - a.s)
            .slice(0, 30)
            .map(({ p }) => ({ href: p.u, title: p.t, desc: p.d || p.h || p.k, badge: p.s, badgeClass: 'badge-page' }));

        visibleHits = [];
        let html = '';
        if (graphHits.length) {
            html += `<div class="dcm-search-group-header">${esc(L.entities)}</div>`;
            graphHits.forEach(h => { html += hitHtml(h, visibleHits.length); visibleHits.push(h); });
        }
        if (pageHits.length) {
            html += `<div class="dcm-search-group-header">${esc(L.pages)}</div>`;
            pageHits.forEach(h => { html += hitHtml(h, visibleHits.length); visibleHits.push(h); });
        }
        if (!visibleHits.length) {
            html = `<div class="dcm-search-noresult">${esc(PAGES ? L.none : L.loading)}</div>`;
            activeIndex = -1;
        } else {
            activeIndex = 0;
        }
        stream.innerHTML = html;
        updateActiveVisualClass();
    }

    function hitHtml(h, i) {
        return `
            <a href="${esc(h.href)}" class="dcm-search-hit" role="option" data-index="${i}">
                <span class="dcm-hit-badge ${esc(h.badgeClass)}">${esc(h.badge)}</span>
                <div class="dcm-hit-meta">
                    <div class="dcm-hit-title">${esc(h.title)}</div>
                    <div class="dcm-hit-desc">${esc(h.desc)}</div>
                </div>
                <i class="fas fa-arrow-right dcm-hit-action-icon" aria-hidden="true"></i>
            </a>`;
    }

    function renderEmptyState() {
        const stream = document.getElementById('dcm-search-results-stream');
        let html = `<div class="dcm-search-empty-state">
            <div class="dcm-search-section-title">${esc(L.suggested)}</div>
            <div class="dcm-search-suggestions">`;
        L.suggestions.forEach(s => {
            html += `<button type="button" class="dcm-search-suggestion-pill" data-q="${esc(s)}">${esc(s)}</button>`;
        });
        html += `</div><div class="dcm-search-tip">${L.tip}</div></div>`;
        stream.innerHTML = html;
        stream.querySelectorAll('.dcm-search-suggestion-pill').forEach(b =>
            b.addEventListener('click', () => window.dcmQuickSearch(b.dataset.q)));
        visibleHits = [];
        activeIndex = -1;
    }

    window.dcmQuickSearch = function (text) {
        const input = document.getElementById('dcm-search-input-node');
        input.value = text;
        input.focus();
        loadPages().then(() => runSearch(text));
    };

    function moveSelection(d) {
        if (!visibleHits.length) return;
        activeIndex = (activeIndex + d + visibleHits.length) % visibleHits.length;
        updateActiveVisualClass();
    }
    function updateActiveVisualClass() {
        document.querySelectorAll('.dcm-search-hit').forEach((node, i) => {
            node.classList.toggle('active', i === activeIndex);
            if (i === activeIndex) node.scrollIntoView({ block: 'nearest' });
        });
    }
    function triggerActiveSelection() {
        if (activeIndex < 0 || !visibleHits.length) return;
        window.location.href = visibleHits[activeIndex].href;
    }

    // ---------- boot ----------
    hydrateKnowledgeGraph();
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initSearchEngine);
    else initSearchEngine();

    window.dcmToggleGlobalSearch = function () { isOpen() ? closeOverlay() : openOverlay(); };
    window.dcmOpenSearch = openOverlay;
    // Compatibility with the former search-engine.js API (window.engine.open()/close()).
    window.engine = window.engine || { open: openOverlay, close: closeOverlay };
})();
